def attribute(rows, runs, expects):
    """Attach provenance labels and per-request diagnostic flags."""
    for record in rows:
        start = record['start']
        end = record['end']
        owner = runs.label_at(start) if end > start else None
        owners = runs.owners_of(start, end)
        flags = set()
        if owner is None:
            flags.add('unattributed')
        if len(owners) > 1:
            flags.add('mixed_owner')
        hosts = record['_identity'][2]
        if not hosts:
            flags.add('missing_host')
        elif len(hosts) > 1:
            flags.add('multiple_host')
        if owner is not None:
            method, target, _ = record['_identity']
            expect = expects[owner]
            if method != expect['method'] or target != expect['target'] or \
                    len(hosts) != 1 or hosts[0].lower() != expect['host']:
                flags.add('identity')
        record['owner'] = owner
        record['owners'] = owners
        record['_flags'] = flags


